#include "CloseToHSL/Core/Runtime/Completion/Routing/TrapCompletionRoutePolicy.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ auto trap=NeutralTrapResult::Trap(TrapRequest::ForInstruction(12,1),NeutralTrapResultKind::InstructionIntercept); auto admission=RuntimeBoundaryAdmissionResult::Allowed(DomainRuntimeAuthorityResult::Allowed); auto service=TrapCompletionRouteService::getDefault(); auto req=std::make_shared<TrapCompletionRouteRequest>(trap,admission,TrapCompletionRouteDescriptor::getRuntimeOwnedPublication(),true,true,4,5,6,EvidenceVisibilityClass::GuestArchitecturalState,TrapCompletionMigrationClass::GuestArchitecturalState); auto route=service->Authorize(req); assert(route->IsFullyRetirable); auto f=service->EvaluateFence(req,route); assert(f->CompletionPublicationAllowed && f->RetirePublicationAllowed && f->Completion->getQualification()==4); req->BackendExecutionAuthorized=false; route=service->Authorize(req); assert(route->DeniesBackendExecution); assert(!service->EvaluateFence(req,route)->CompletionPublicationAllowed); req->BackendExecutionAuthorized=true; req->RouteDescriptor=TrapCompletionRouteDescriptor::getRuntimeOwnedCompletionPublication(); route=service->Authorize(req); assert(route->CompletionPublicationAuthorizedOnly); f=service->EvaluateFence(req,route); assert(f->IsCompletionOnly && f->IsRetireDenied); req->RouteDescriptor=TrapCompletionRouteDescriptor::getRuntimeOwnedPublication(); req->CompletionEvidenceClass=EvidenceVisibilityClass::HostOwnedRuntimeEvidence; route=service->Authorize(req); f=service->EvaluateFence(req,route); assert(f->IsCompletionOnly); }
